sub execute {
    my $self = shift;
    my $sqitch = $self->sqitch;
    my $plan = $sqitch->plan;

    # Get the target change or tag from the command line arguments
    my $target = $self->arg or hurl 'checkout.no_target';

    # Find the target change in the plan
    my $change = $plan->get($target);
    hurl checkout => __x('No such change or tag: {target}', target => $target) unless $change;

    # Get the current change
    my $current = $plan->current;

    # If the target is the current change, do nothing
    return unless $change ne $current;

    # Revert changes from current to target
    if ($current) {
        my @revert = $plan->changes_after($current, $change);
        for my $revert (@revert) {
            $self->revert_change($revert);
        }
    }

    # Deploy changes from target to current
    my @deploy = $plan->changes_after($change, $current);
    for my $deploy (@deploy) {
        $self->deploy_change($deploy);
    }

    # Update the current change to the target
    $plan->current($change);
}

