sub emit_state {
    my ( $self, $state ) = @_;
    my $target = $self->target;
    my $engine = $target->engine;
    my $plan   = $target->plan;

    # Extract state information
    my $current_change = $state->{change};
    my $current_tags   = $state->{tags};
    my $current_date   = $state->{date};

    # Find the current change in the plan
    my $change = try {
        $plan->get_change($current_change);
    } catch {
        hurl sqitch_error __x(
            'Could not find change {change} in plan',
            change => $current_change,
        );
    };

    # Emit the state information
    print __x(
        'Current state: {change} @{[ $current_date ? "at " . $current_date : "" ]}',
        change => $change->name,
    ), "\n";

    # Emit tags if any
    if (@$current_tags) {
        print __x('Tags: {tags}', tags => join(', ', @$current_tags)), "\n";
    }
}

