sub format {
    my $self = shift;
    my ($format, $item) = @_;

    # Ensure $item is a hash reference
    hurl 'Item must be a hash reference' unless ref $item eq 'HASH';

    # Create a formatter object if not already created
    my $formatter = $self->{formatter} || String::Formatter->new;

    # Define a callback for the formatter
    my $callback = sub {
        my ($spec, $attr) = @_;
        my $value = $item->{$attr} // '';

        # Handle date formatting
        if ($attr =~ /^(committed|planned)_at$/) {
            my $date_format = $self->{date_format} || 'iso';
            $value = $value->strftime($date_format) if $value->can('strftime');
        }

        # Handle abbreviations
        if ($attr eq 'change_id' && $spec =~ /^%(\d*)h$/) {
