    open my $fh, '<:encoding(UTF-8)', $file
        or hurl file => __x(
            'Cannot open plan file {file}: {error}',
            file  => $file,
            error => $!
        );

    my $data = $self->_parse($file, $fh);
    close $fh;

    # Store the parsed data.
    $self->{changes} = ChangeList->new(changes => $data->{changes});
    $self->{lines}   = LineList->new(lines   => $data->{lines});
    $self->{pragmas} = $data->{pragmas};

    # Initialize position.
    $self->position(-1);

    return $data;
}
