use App::Sqitch::X qw(hurl);
use utf8;
use strict;
use List::Util;
use Locale::TextDomain qw(App-Sqitch);
sub _offset($) {
    # Look for symbolic references.
    if ( $_[0] =~ s{(?<![$punct])([~^])(?:(\1)|(\d+))?\z}{} ) {
        my $offset = $3 // ($2 ? 2 : 1);
