        ($project, $change) = ($string =~ m/^($name_re):($name_re)$/);
        if (!defined $project) {
            ($change, $tag) = ($string =~ m/^($name_re)@($name_re)$/);
            if (!defined $change) {
                $change = $string if $string =~ /^$name_re$/;
            }
        }
    }

    return undef unless defined $change || defined $tag;

    return {
        project   => $project,
        conflicts => $conflicts,
        change    => $change,
        tag       => $tag,
    };
}
