    # Validate and construct the target
    unless ($name) {
        hurl __x('No target name provided and no default target set');
    }

    my $target = App::Sqitch::Target->new(
        name   => $name,
        uri    => $uri,
        engine => $engine,
    );

    # Apply other properties
    for my $key (qw(deploy revert verify reworked reworked_deploy reworked_revert reworked_verify extension)) {
        $target->$key($p{$key}) if exists $p{$key};
        $target->$key($properties->{$key}) if !exists $p{$key} && exists $properties->{$key};
    }

    return $target;
}

